// Visitors: f(const ComponentDesc&, Struct&) for the flat components, f(const ComponentDesc&, RecordPool&) for the pools.
template <class S, class F>
void visit_components(S& s, F&& f) {
  f(kMindStaticDesc, s.mind_static);
  f(kMindDynamicDesc, s.mind_dynamic);
  f(kBodyDesc, s.body);
  f(kNeedsDesc, s.needs);
  f(kLifecycleDesc, s.lifecycle);
  f(kCarrierDesc, s.carrier);
  f(kActivityDesc, s.activity);
  f(kBeliefsDesc, s.beliefs);
  f(kRelationsDesc, s.relations);
  f(kMemoryDesc, s.memory);
  f(kGoalsDesc, s.goals);
}
template <class S, class F>
void visit_pools(S& s, F&& f) {
  f(kBeliefDesc, s.belief_records);
  f(kEntityPerceptDesc, s.entity_percept_records);
  f(kEpisodeDesc, s.episode_records);
  f(kEventSeenDesc, s.event_seen_records);
  f(kGoalDesc, s.goal_records);
  f(kIntentionDesc, s.intention_records);
  f(kLocusDesc, s.locus_records);
  f(kPerceptDesc, s.percept_records);
  f(kPlacePerceptDesc, s.place_percept_records);
  f(kRelationDesc, s.relation_records);
  f(kRequestDesc, s.request_records);
  f(kSkillDesc, s.skill_records);
}

